<?php $summary=['subtotal'=>0,'delivery'=>0,'tax'=>0,'fee'=>0,'total'=>0];foreach($rows as $r){if(!in_array($r['payment_status'],['paid','demo_paid','partially_refunded','refunded'],true))continue;foreach(['subtotal'=>'refunded_merchandise','delivery'=>'refunded_delivery','tax'=>'refunded_tax','fee'=>'refunded_fee','total'=>'refunded'] as $key=>$refundKey)$summary[$key]+=(int)$r[$key]-(int)$r[$refundKey];} ?>
<div class="page-heading"><div><div class="eyebrow">KNOW WHERE YOUR BUSINESS STANDS</div><h1>Purchase history & expenses<span class="green">.</span></h1><p>Basic expense tracking. Confirmed totals include demo transactions, with refunds deducted.</p></div><a class="btn btn-outline-secondary" href="/expenses/export?<?= e(http_build_query($_GET)) ?>">Export CSV ↗</a></div><form method="get" class="panel filter-form"><label>From<input type="date" name="from" value="<?= e($from) ?>" required></label><label>To<input type="date" name="to" value="<?= e($to) ?>" required></label><label>Supplier<select name="supplier"><option value="">All suppliers</option><?php foreach($suppliers as $s):?><option value="<?= $s['user_id'] ?>" <?= (string)$s['user_id']===($_GET['supplier']??'')?'selected':'' ?>><?= e($s['name']) ?></option><?php endforeach;?></select></label><label>Category<select name="category"><option value="">All categories</option><?php foreach($categories as $c):?><option value="<?= $c['id'] ?>" <?= (string)$c['id']===($_GET['category']??'')?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach;?></select></label><label>Payment<select name="status"><option value="">All statuses</option><?php foreach(['paid','demo_paid','pending','refunded','partially_refunded','failed','expired','cancelled'] as $s):?><option value="<?= $s ?>" <?= $s===($_GET['status']??'')?'selected':'' ?>><?= e(str_replace('_',' ',$s)) ?></option><?php endforeach;?></select></label><button class="btn btn-primary">Apply</button></form><div class="stats-grid expense-stats"><?php foreach(['total'=>'Net confirmed total','subtotal'=>'Merchandise','delivery'=>'Delivery','tax'=>'Taxes','fee'=>'Buyer fees'] as $key=>$label):?><div class="stat-card"><span><?= $label ?></span><strong><?= money($summary[$key]) ?></strong></div><?php endforeach;?></div><p class="small-muted">Category filters select orders containing that category; displayed delivery, tax and fee totals remain whole-order amounts. CSV lists all selected statuses; pending and failed payments are excluded from confirmed summary totals. This is not a complete accounting system.</p><div class="table-panel"><table><thead><tr><th>Order / date</th><th>Supplier</th><th>Payment</th><th>Merchandise</th><th>Delivery</th><th>Tax</th><th>Fee</th><th>Refund</th><th>Net</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a href="/order?id=<?= $r['id'] ?>">#<?= $r['id'] ?></a><small><?= e(substr($r['created_at'],0,10)) ?></small></td><td><?= e($r['supplier']) ?></td><td><span class="badge <?= $r['mode']==='demo'?'demo-badge':'soft-badge' ?>"><?= e(str_replace('_',' ',$r['payment_status']).($r['mode']==='demo'?' · demo':' · test')) ?></span></td><td><?= money($r['subtotal']) ?></td><td><?= money($r['delivery']) ?></td><td><?= money($r['tax']) ?></td><td><?= money($r['fee']) ?></td><td><?= money($r['refunded']) ?></td><td><strong><?= money($r['total']-$r['refunded']) ?></strong></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty-state">No purchases in this date range.</div><?php endif;?></div>
